import common_default from "./form-config/common.js";
import App_default from "./App.js";
import configs from "./form-config/index.js";
import { mergeFormInstallOptions } from "./mergeFormOptions.js";
import { COMPONENT_GROUP_LIST } from "./component-group-list.js";
import { createApp, getCurrentInstance, onBeforeUnmount } from "vue";
import cssStyle from "element-plus/dist/index.css?raw";
import { Layout, editorService, formPlugin, injectStyle, propsService, uiService } from "@tmagic/editor";
// runtime/tmagic-form/src/index.ts
var propsConfigs = configs;
var useRuntime = ({ plugins = [], fillConfig = (config) => config, formOptions = {} } = {}) => {
	const hostFormOptions = getCurrentInstance()?.appContext.config.globalProperties.$MAGIC_FORM;
	const render = (stage) => {
		const doc = stage.renderer?.getDocument();
		if (doc) {
			injectStyle(doc, cssStyle);
			injectStyle(doc, `html,
          body,
          #app {
            width: 100%;
            height: 100%;
            margin: 0;
          }
          ::-webkit-scrollbar {
            width: 0;
          }
        `);
		}
		const el = globalThis.document.createElement("div");
		el.id = "app";
		el.style.overflow = "auto";
		const vueApp = createApp(App_default, {
			stage,
			fillConfig
		});
		vueApp.use(formPlugin, mergeFormInstallOptions(hostFormOptions, formOptions));
		plugins.forEach((plugin) => vueApp.use(plugin));
		vueApp.mount(el);
		setTimeout(() => {
			uiService.set("showRule", false);
		});
		return el;
	};
	propsService.usePlugin({ async afterFillConfig(config, itemConfig, labelWidth = "80px") {
		return [{
			type: "tab",
			items: [{
				title: "属性",
				labelWidth,
				items: [...common_default, ...itemConfig]
			}]
		}];
	} });
	editorService.usePlugin({ async afterGetLayout() {
		return Layout.RELATIVE;
	} });
	onBeforeUnmount(() => {
		propsService.removeAllPlugins();
		editorService.removeAllPlugins();
	});
	return { render };
};
export { COMPONENT_GROUP_LIST, propsConfigs, useRuntime };
