import { error } from "../logger.js";
import { EventEmitter } from "events";
// packages/editor/src/utils/dep/idle-task.ts
/**
* 回调因 timeout 触发（主线程一直没有空闲）时，单次回调执行任务的时间预算，单位 ms
* 参考一帧内可让出的余量：既保证队列有进展，又不长时间阻塞主线程
*/
var TIMEOUT_RUN_BUDGET = 5;
/**
* 回调因 timeout 触发时，每两次读取时钟之间执行的任务数
* 与空闲时间 <=5ms 时的批量保持一致，避免每个任务都读一次时钟
*/
var TIMEOUT_BATCH_SIZE = 10;
globalThis.requestIdleCallback = globalThis.requestIdleCallback || function(cb) {
	const start = Date.now();
	return setTimeout(() => {
		cb({
			didTimeout: false,
			timeRemaining() {
				return Math.max(0, 50 - (Date.now() - start));
			}
		});
	}, 1);
};
globalThis.cancelIdleCallback = globalThis.cancelIdleCallback || function(handle) {
	clearTimeout(handle);
};
var IdleTask = class extends EventEmitter {
	taskList = [];
	hightLevelTaskList = [];
	taskHandle = null;
	constructor() {
		super();
		this.setMaxListeners(1e3);
	}
	enqueueTask(taskHandler, taskData, isHightLevel = false) {
		(isHightLevel ? this.hightLevelTaskList : this.taskList).push({
			handler: taskHandler,
			data: taskData
		});
		if (!this.taskHandle) this.taskHandle = globalThis.requestIdleCallback(this.runTaskQueue.bind(this), { timeout: 1e4 });
	}
	clearTasks() {
		if (this.taskHandle) globalThis.cancelIdleCallback(this.taskHandle);
		this.hightLevelTaskList = [];
		this.taskList = [];
		this.taskHandle = null;
		this.emit("update-task-length", {
			length: this.getTaskLength(),
			hightLevelLength: this.hightLevelTaskList.length
		});
	}
	on(eventName, listener) {
		return super.on(eventName, listener);
	}
	once(eventName, listener) {
		return super.once(eventName, listener);
	}
	emit(eventName, ...args) {
		return super.emit(eventName, ...args);
	}
	runTaskQueue(deadline) {
		this.taskHandle = null;
		try {
			if (deadline.didTimeout) {
				const start = Date.now();
				do
					this.runTaskBatch(TIMEOUT_BATCH_SIZE);
				while (this.getTaskLength() && Date.now() - start < TIMEOUT_RUN_BUDGET);
				return;
			}
			while (deadline.timeRemaining() > 0 && this.getTaskLength()) {
				const timeRemaining = deadline.timeRemaining();
				let times = 0;
				if (timeRemaining <= 5) times = 10;
				else if (timeRemaining <= 10) times = 100;
				else if (timeRemaining <= 15) times = 300;
				else times = 600;
				this.runTaskBatch(times);
			}
		} finally {
			this.finishRun();
		}
	}
	/**
	* 执行一批任务，队列被清空时提前结束
	*/
	runTaskBatch(times) {
		for (let i = 0; i < times; i++) {
			const task = this.hightLevelTaskList.length > 0 ? this.hightLevelTaskList.shift() : this.taskList.shift();
			if (task) this.runTask(task);
			if (!this.getTaskLength()) break;
		}
	}
	/**
	* 单个任务失败不能中断整个队列，否则后续任务永远不会被执行，
	* 依赖收集会停在半路（收集中状态与剩余任务数都不再变化）
	*/
	runTask(task) {
		try {
			task.handler(task.data);
		} catch (e) {
			error("magic editor: 空闲任务执行失败", e);
		}
	}
	finishRun() {
		try {
			if (!this.hightLevelTaskList.length) this.emit("hight-level-finish");
		} finally {
			if (this.getTaskLength()) {
				if (!this.taskHandle) this.taskHandle = globalThis.requestIdleCallback(this.runTaskQueue.bind(this), { timeout: 300 });
			} else this.emit("finish");
			this.emit("update-task-length", {
				length: this.getTaskLength(),
				hightLevelLength: this.hightLevelTaskList.length
			});
		}
	}
	getTaskLength() {
		return this.taskList.length + this.hightLevelTaskList.length;
	}
};
export { IdleTask };
