import { addDataSourceTargets, classifyUpdatedNodes, getDataSourceRecollectTypes, removeDataSourceTargets, removeTargetDeps, resetDepTargets, writeTargetDeps } from "./utils/dep.js";
import { getNodes, isPage } from "@tmagic/utils";
import { DepTargetType, NodeType, createCodeBlockTarget } from "@tmagic/core";
// packages/editor/src/sdk/wiring.ts
var pendingSelects = /* @__PURE__ */ new WeakMap();
/** root 变化后自动选中节点是异步的，需要时可以等它完成 */
var whenWiringSettled = (ctx) => pendingSelects.get(ctx) ?? Promise.resolve();
var bindWiring = (ctx) => {
	const { editor, codeBlock, dataSource, dep, reactivity } = ctx;
	const getPageIdByNode = (node) => {
		if (isPage(node)) return node.id;
		return editor.getNodeInfo(node.id).page?.id;
	};
	const collect = (nodes, deep, type) => {
		for (const node of nodes) {
			if (node.type === NodeType.ROOT) continue;
			dep.collect([node], { pageId: getPageIdByNode(node) }, deep, type);
		}
	};
	/** root 变化后选中原来的节点，没有则选中第一个页面（与浏览器端一致） */
	const selectAfterRootChange = (root) => {
		const nodeId = editor.get("node")?.id;
		const node = nodeId ? editor.getNodeById(nodeId) : null;
		let selecting;
		if (node && node !== root) selecting = editor.select(node.id);
		else if (root.items?.length) selecting = editor.select(root.items[0]);
		else if (root.id) {
			editor.set("nodes", [root]);
			editor.set("parent", null);
			editor.set("page", null);
		}
		if (selecting) pendingSelects.set(ctx, selecting.catch(() => {}));
	};
	const rootChangeHandler = (root) => {
		if (!root) return;
		root.codeBlocks = root.codeBlocks || {};
		root.dataSources = root.dataSources || [];
		codeBlock.setCodeDsl(root.codeBlocks);
		dataSource.set("dataSources", root.dataSources);
		resetDepTargets(dep, root.codeBlocks, dataSource.get("dataSources"), reactivity.reactive);
		if (Array.isArray(root.items)) {
			dep.clearIdleTasks();
			collect(root.items, true);
		} else {
			dep.clear();
			delete root.dataSourceDeps;
			delete root.dataSourceCondDeps;
		}
		selectAfterRootChange(root);
	};
	const nodeAddHandler = (nodes) => collect(nodes, true);
	const nodeUpdateHandler = (data) => {
		const { needRecollectNodes, normalNodes } = classifyUpdatedNodes(ctx, data);
		collect(needRecollectNodes, true, DepTargetType.DATA_SOURCE);
		collect(needRecollectNodes, true, DepTargetType.DATA_SOURCE_COND);
		const updatedNodes = [...needRecollectNodes, ...normalNodes];
		collect(updatedNodes, true, DepTargetType.CODE_BLOCK);
		collect(updatedNodes, true, DepTargetType.DATA_SOURCE_METHOD);
	};
	const nodeRemoveHandler = (nodes) => dep.clear(nodes);
	const historyChangeHandler = (page) => collect([page], true);
	const dataSourceAddHandler = (config) => addDataSourceTargets(dep, config, reactivity.reactive);
	const dataSourceUpdateHandler = (config, { changeRecords }) => {
		const types = getDataSourceRecollectTypes(changeRecords);
		const items = editor.get("root")?.items;
		if (!types || !Array.isArray(items)) return;
		dep.clearIdleTasks();
		removeDataSourceTargets(dep, config.id, types);
		addDataSourceTargets(dep, config, reactivity.reactive, types);
		for (const type of types) collect(items, true, type);
	};
	const dataSourceRemoveHandler = (id) => {
		const root = editor.get("root");
		if (!root) return;
		const nodes = getNodes(Object.keys(root.dataSourceDeps?.[id] || {}), root.items);
		for (const type of [
			DepTargetType.DATA_SOURCE,
			DepTargetType.DATA_SOURCE_COND,
			DepTargetType.DATA_SOURCE_METHOD
		]) collect(nodes, false, type);
		removeDataSourceTargets(dep, id);
	};
	const codeBlockAddOrUpdateHandler = (id, content) => {
		if (dep.hasTarget(id, DepTargetType.CODE_BLOCK)) {
			dep.getTarget(id, DepTargetType.CODE_BLOCK).name = content.name;
			return;
		}
		dep.addTarget(createCodeBlockTarget(id, content));
	};
	const codeBlockRemoveHandler = (id) => dep.removeTarget(id, DepTargetType.CODE_BLOCK);
	const targetAddHandler = (target) => writeTargetDeps(editor.get("root"), target);
	const targetRemoveHandler = (id, type) => removeTargetDeps(editor.get("root"), id, type);
	const listeners = [
		[
			editor,
			"history-change",
			historyChangeHandler
		],
		[
			editor,
			"root-change",
			rootChangeHandler
		],
		[
			editor,
			"add",
			nodeAddHandler
		],
		[
			editor,
			"remove",
			nodeRemoveHandler
		],
		[
			editor,
			"update",
			nodeUpdateHandler
		],
		[
			dataSource,
			"add",
			dataSourceAddHandler
		],
		[
			dataSource,
			"update",
			dataSourceUpdateHandler
		],
		[
			dataSource,
			"remove",
			dataSourceRemoveHandler
		],
		[
			codeBlock,
			"addOrUpdate",
			codeBlockAddOrUpdateHandler
		],
		[
			codeBlock,
			"remove",
			codeBlockRemoveHandler
		],
		[
			dep,
			"add-target",
			targetAddHandler
		],
		[
			dep,
			"remove-target",
			targetRemoveHandler
		]
	];
	for (const [service, event, handler] of listeners) service.on(event, handler);
	const root = editor.get("root");
	if (root) rootChangeHandler(root);
	return { unbind() {
		for (const [service, event, handler] of listeners) service.off(event, handler);
	} };
};
export { bindWiring, classifyUpdatedNodes, whenWiringSettled };
