import { Mode, ZIndex } from "./const.js";
import Rule from "./Rule.js";
import { getScrollParent, isDocumentVisible, isElementVisible, isFixedParent, scrollElementIntoView } from "./util.js";
import { createDiv, getDocument, injectStyle } from "@tmagic/core";
// packages/stage/src/StageMask.ts
var wrapperClassName = "editor-mask-wrapper";
var hideScrollbar = () => {
	injectStyle(getDocument(), `.${wrapperClassName}::-webkit-scrollbar { width: 0 !important; display: none }`);
};
var createContent = () => createDiv({
	className: "editor-mask",
	cssText: `
    position: absolute;
    top: 0;
    left: 0;
    transform: translate3d(0, 0, 0);
  `
});
var createWrapper = () => {
	const el = createDiv({
		className: wrapperClassName,
		cssText: `
      position: absolute;
      top: 0;
      left: 0;
      height: 100%;
      width: 100%;
      overflow: hidden;
      z-index: ${ZIndex.MASK};
    `
	});
	hideScrollbar();
	return el;
};
/**
* 蒙层
* @description 用于拦截页面的点击动作，避免点击时触发组件自身动作；在编辑器中点击组件应当是选中组件；
*/
var StageMask = class extends Rule {
	content = createContent();
	wrapper;
	page = null;
	scrollTop = 0;
	scrollLeft = 0;
	width = 0;
	height = 0;
	wrapperHeight = 0;
	wrapperWidth = 0;
	maxScrollTop = 0;
	maxScrollLeft = 0;
	mode = Mode.ABSOLUTE;
	pageScrollParent = null;
	intersectionObserver = null;
	wrapperResizeObserver = null;
	constructor(options) {
		const wrapper = createWrapper();
		super(wrapper, options);
		this.wrapper = wrapper;
		this.content.addEventListener("wheel", this.mouseWheelHandler);
		this.wrapper.appendChild(this.content);
	}
	setMode(mode) {
		this.mode = mode;
		this.scroll();
		this.content.dataset.mode = mode;
		if (mode === Mode.FIXED) {
			this.content.style.width = `${this.wrapperWidth}px`;
			this.content.style.height = `${this.wrapperHeight}px`;
		} else {
			this.content.style.width = `${this.width}px`;
			this.content.style.height = `${this.height}px`;
		}
	}
	/**
	* 初始化视窗和蒙层监听，监听元素是否在视窗区域、监听mask蒙层所在的wrapper大小变化
	* @description 初始化视窗和蒙层监听；切换到新页面 DOM 时重置滚动
	* @param page 页面Dom节点
	*/
	observe(page) {
		if (!page) return;
		const pageChanged = this.page !== page;
		this.page = page;
		this.initObserverIntersection();
		this.initObserverWrapper();
		if (pageChanged) {
			this.pageScrollParent?.scrollTo({
				top: 0,
				left: 0
			});
			this.scrollTop = 0;
			this.scrollLeft = 0;
			this.scroll();
		}
		this.syncPageSize();
	}
	/**
	* 处理页面大小变更，同步页面和 mask 大小
	* @description 仅处理当前 page 且仍挂载在文档中的 entry；非当前页、已卸载或宽高为 0 的回调会被忽略
	* @param entries ResizeObserverEntry，获取页面最新大小
	*/
	pageResize(entries) {
		if (!this.page || !entries.length) return;
		const entry = entries.find((item) => item.target === this.page);
		if (!entry) return;
		const { target } = entry;
		if (!target.isConnected) return;
		this.applyPageSize(target.clientWidth, target.clientHeight);
	}
	/**
	* 监听一个组件是否在画布可视区域内
	* @param el 被选中的组件，可能是左侧目录树中选中的
	*/
	observerIntersection(el) {
		this.intersectionObserver?.observe(el);
	}
	/**
	* 挂载Dom节点
	* @param el 将蒙层挂载到该Dom节点上
	*/
	mount(el) {
		if (!this.content) throw new Error("content 不存在");
		el.appendChild(this.wrapper);
	}
	setLayout(el) {
		this.setMode(isFixedParent(el) ? Mode.FIXED : Mode.ABSOLUTE);
	}
	/**
	* 将元素滚动到画布可视区域内
	* @description 页面不可见时不做滚动：此时滚动既无视觉效果，又会记录错误的滚动偏移
	* @param el 目标元素
	*/
	scrollIntoView(el) {
		if (!this.isPageVisible()) return;
		if (!this.page || el.getBoundingClientRect().left >= this.page.scrollWidth) return;
		const scrollParent = getScrollParent(el);
		if (scrollParent && scrollParent !== this.pageScrollParent) {
			this.scrollIntoView(scrollParent);
			return;
		}
		if (!this.pageScrollParent) return;
		scrollElementIntoView(el, this.pageScrollParent);
		this.scrollLeft = this.pageScrollParent.scrollLeft;
		this.scrollTop = this.pageScrollParent.scrollTop;
		this.scroll();
	}
	/**
	* 销毁实例
	*/
	destroy() {
		super.destroy();
		this.content?.remove();
		this.page = null;
		this.pageScrollParent = null;
		this.intersectionObserver?.disconnect();
		this.wrapperResizeObserver?.disconnect();
	}
	on(eventName, listener) {
		return super.on(eventName, listener);
	}
	emit(eventName, ...args) {
		return super.emit(eventName, ...args);
	}
	/**
	* 监听选中元素是否在画布可视区域内，如果目标元素不在可视区域内，通过滚动使该元素出现在可视区域
	*/
	initObserverIntersection() {
		this.pageScrollParent = getScrollParent(this.page) || null;
		this.intersectionObserver?.disconnect();
		if (typeof IntersectionObserver !== "undefined") this.intersectionObserver = new IntersectionObserver((entries) => {
			entries.forEach((entry) => {
				const { target, intersectionRatio } = entry;
				if (!this.isPageVisible()) return;
				if (intersectionRatio <= 0) this.scrollIntoView(target);
				this.intersectionObserver?.unobserve(target);
			});
		}, {
			root: this.pageScrollParent,
			rootMargin: "0px",
			threshold: 1
		});
	}
	/**
	* 监听mask的容器大小变化
	*/
	initObserverWrapper() {
		this.wrapperResizeObserver?.disconnect();
		if (typeof ResizeObserver !== "undefined") {
			this.wrapperResizeObserver = new ResizeObserver((entries) => {
				const [entry] = entries;
				const { clientHeight, clientWidth } = entry.target;
				this.wrapperHeight = clientHeight;
				this.wrapperWidth = clientWidth;
				if (this.mode === Mode.FIXED) {
					this.content.style.width = `${this.wrapperWidth}px`;
					this.content.style.height = `${this.wrapperHeight}px`;
				}
				this.setMaxScrollLeft();
				this.setMaxScrollTop();
			});
			this.wrapperResizeObserver.observe(this.wrapper);
		}
	}
	scroll() {
		this.fixScrollValue();
		let { scrollLeft, scrollTop } = this;
		if (this.pageScrollParent) this.pageScrollParent.scrollTo({
			top: scrollTop,
			left: scrollLeft
		});
		if (this.mode === Mode.FIXED) {
			scrollLeft = 0;
			scrollTop = 0;
		}
		this.scrollRule(scrollTop);
		this.scrollTo(scrollLeft, scrollTop);
	}
	scrollTo(scrollLeft, scrollTop) {
		this.content.style.transform = `translate3d(${-scrollLeft}px, ${-scrollTop}px, 0)`;
		const event = new CustomEvent("customScroll", { detail: {
			scrollLeft: this.scrollLeft,
			scrollTop: this.scrollTop
		} });
		this.content.dispatchEvent(event);
	}
	/**
	* 页面是否可见
	* @description 页面未挂载、或画布容器被隐藏（如编辑器切到其他面板）时页面不可见；
	* 蒙层与页面所在的 iframe 挂载在同一容器中，容器隐藏时页面内部元素仍可能是"可见"的，因此额外判断蒙层；
	* 浏览器 tab 不可见（切到其他标签页、窗口最小化）时同样视为不可见
	*/
	isPageVisible() {
		if (!isDocumentVisible(this.page?.ownerDocument) || !isDocumentVisible(this.wrapper.ownerDocument)) return false;
		if (!isElementVisible(this.page)) return false;
		return !this.wrapper.isConnected || isElementVisible(this.wrapper);
	}
	/**
	* 从当前页面同步蒙层宽高，并修正滚动偏移
	*/
	syncPageSize() {
		if (!this.page?.isConnected) return;
		this.applyPageSize(this.page.clientWidth, this.page.clientHeight);
	}
	/**
	* 应用页面尺寸到蒙层；宽高为 0 时忽略，避免切换/布局过程中把 editor-mask 置空
	*/
	applyPageSize(clientWidth, clientHeight) {
		if (clientWidth <= 0 || clientHeight <= 0) return;
		this.setHeight(clientHeight);
		this.setWidth(clientWidth);
		this.scroll();
	}
	/**
	* 设置蒙层高度
	* @param height 高度
	*/
	setHeight(height) {
		this.height = height;
		this.setMaxScrollTop();
		if (this.mode !== Mode.FIXED) this.content.style.height = `${height}px`;
	}
	/**
	* 设置蒙层宽度
	* @param width 宽度
	*/
	setWidth(width) {
		this.width = width;
		this.setMaxScrollLeft();
		if (this.mode !== Mode.FIXED) this.content.style.width = `${width}px`;
	}
	/**
	* 计算并设置最大滚动宽度
	*/
	setMaxScrollLeft() {
		this.maxScrollLeft = Math.max(this.width - this.wrapperWidth, 0);
	}
	/**
	* 计算并设置最大滚动高度
	*/
	setMaxScrollTop() {
		this.maxScrollTop = Math.max(this.height - this.wrapperHeight, 0);
	}
	/**
	* 修复滚动距离
	* 由于滚动容器变化等因素，会导致当前滚动的距离不正确
	*/
	fixScrollValue() {
		if (this.scrollTop < 0) this.scrollTop = 0;
		if (this.scrollLeft < 0) this.scrollLeft = 0;
		if (this.maxScrollTop < this.scrollTop) this.scrollTop = this.maxScrollTop;
		if (this.maxScrollLeft < this.scrollLeft) this.scrollLeft = this.maxScrollLeft;
	}
	mouseWheelHandler = (event) => {
		if (!this.page) throw new Error("page 未初始化");
		const { deltaY, deltaX } = event;
		if (this.page.clientHeight < this.wrapperHeight && deltaY) return;
		if (this.page.clientWidth < this.wrapperWidth && deltaX) return;
		if (this.maxScrollTop > 0) this.scrollTop = this.scrollTop + deltaY;
		if (this.maxScrollLeft > 0) this.scrollLeft = this.scrollLeft + deltaX;
		this.scroll();
		this.emit("scroll", event);
	};
};
export { StageMask as default };
